CREATE OR REPLACE FUNCTION public.effective_tenant_modules(p_tenant uuid) RETURNS TABLE(module_code text,is_enabled boolean,valid_until date) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NOT (coalesce(auth.role(),'')='service_role' OR can_portal_read(auth.uid(),'commercial') OR can_manage_partner_billing((SELECT partner_id FROM tenants WHERE id=p_tenant)) OR EXISTS(SELECT 1 FROM profiles WHERE id=auth.uid() AND tenant_id=p_tenant) OR EXISTS(SELECT 1 FROM support_sessions WHERE user_id=auth.uid() AND tenant_id=p_tenant AND ended_at IS NULL)) THEN RAISE EXCEPTION 'Keine Berechtigung'; END IF;
RETURN QUERY WITH coverage AS (SELECT s.ended_on,m.module_code code FROM license_sales s CROSS JOIN LATERAL (SELECT pm.module_code FROM pricing_package_modules pm WHERE s.product_kind='package' AND pm.package_code=s.product_code UNION SELECT unnest(CASE WHEN s.product_kind='unit' AND s.product_code='charge_point' THEN ARRAY['ev_charging','adhoc_payment'] WHEN s.product_kind='unit' AND s.product_code='extra_location' THEN ARRAY['locations'] ELSE ARRAY[]::text[] END)) m WHERE s.tenant_id=p_tenant), permanent AS (SELECT pm.module_code code FROM tenant_package_bookings b JOIN pricing_package_modules pm ON pm.package_code=b.package_code WHERE b.tenant_id=p_tenant AND b.cancelled_at IS NULL UNION SELECT pm.module_code FROM pricing_packages p JOIN pricing_package_modules pm ON pm.package_code=p.code WHERE p.always_active)
SELECT tm.module_code,tm.is_enabled AND (coalesce(tm.individual_grant,false) OR EXISTS(SELECT 1 FROM permanent p WHERE p.code=tm.module_code) OR NOT EXISTS(SELECT 1 FROM coverage c WHERE c.code=tm.module_code) OR EXISTS(SELECT 1 FROM coverage c WHERE c.code=tm.module_code AND (c.ended_on IS NULL OR c.ended_on >= (now() AT TIME ZONE 'Europe/Berlin')::date))),CASE WHEN coalesce(tm.individual_grant,false) OR EXISTS(SELECT 1 FROM permanent p WHERE p.code=tm.module_code) OR NOT EXISTS(SELECT 1 FROM coverage c WHERE c.code=tm.module_code) OR EXISTS(SELECT 1 FROM coverage c WHERE c.code=tm.module_code AND c.ended_on IS NULL) THEN NULL ELSE (SELECT max(c.ended_on) FROM coverage c WHERE c.code=tm.module_code) END FROM tenant_modules tm WHERE tm.tenant_id=p_tenant;
END $$;
REVOKE ALL ON FUNCTION public.effective_tenant_modules(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.effective_tenant_modules(uuid) TO authenticated,service_role;
CREATE TABLE IF NOT EXISTS public.license_sale_corrections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sale_id uuid NOT NULL REFERENCES public.license_sales(id),tenant_id uuid NOT NULL REFERENCES public.tenants(id),actor_id uuid,created_at timestamptz NOT NULL DEFAULT now(),before_data jsonb NOT NULL,after_data jsonb NOT NULL);
GRANT SELECT ON public.license_sale_corrections TO authenticated;
GRANT ALL ON public.license_sale_corrections TO service_role;
ALTER TABLE public.license_sale_corrections ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='license_sale_corrections' AND policyname='Commercial owners read corrections') THEN CREATE POLICY "Commercial owners read corrections" ON public.license_sale_corrections FOR SELECT TO authenticated USING(can_portal_read(auth.uid(),'commercial') OR can_manage_partner_billing((SELECT partner_id FROM license_sales WHERE id=sale_id))); END IF; END $$;
CREATE OR REPLACE FUNCTION public.audit_license_sale_correction() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF ROW(OLD.sale_price,OLD.quantity,OLD.cadence,OLD.customer_discount_pct,OLD.discount_starts_on,OLD.discount_ends_on,OLD.discount_after) IS DISTINCT FROM ROW(NEW.sale_price,NEW.quantity,NEW.cadence,NEW.customer_discount_pct,NEW.discount_starts_on,NEW.discount_ends_on,NEW.discount_after) THEN INSERT INTO license_sale_corrections(sale_id,tenant_id,actor_id,before_data,after_data) VALUES(NEW.id,NEW.tenant_id,auth.uid(),to_jsonb(OLD),to_jsonb(NEW)); END IF; RETURN NEW; END $$;
CREATE OR REPLACE TRIGGER audit_license_sale_correction AFTER UPDATE ON public.license_sales FOR EACH ROW EXECUTE FUNCTION public.audit_license_sale_correction();
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.correct_license_sale(uuid,numeric,integer,text,numeric,date,date,text,text)'::regprocedure) INTO d;
d:=replace(d,'first_start date; frozen boolean; used integer;','first_start date; last_end date; cursor_day date; frozen boolean; used integer;');
d:=replace(d,'SELECT min(period_start) INTO first_start FROM license_billing_events WHERE sale_id=s.id;','SELECT min(period_start),max(period_end) INTO first_start,last_end FROM license_billing_events WHERE sale_id=s.id;');
d:=replace(d,'IF NOT frozen THEN PERFORM bill_license_sale(s.id,coalesce(first_start,s.starts_on),true); END IF;','IF NOT frozen THEN cursor_day:=coalesce(first_start,s.starts_on); LOOP PERFORM bill_license_sale(s.id,cursor_day,true); SELECT next_period INTO cursor_day FROM license_sales WHERE id=s.id; EXIT WHEN cursor_day IS NULL OR cursor_day>coalesce(last_end,s.starts_on) OR (p_after=''end'' AND cursor_day>p_to); END LOOP; END IF;'); EXECUTE d; END $$;
NOTIFY pgrst,'reload schema';